const srcs=[['1:215',0],['1:219',32],['1:216',64],['1:217',96]];
const GRAY='#6D6E76';
const S=h=>({type:'SOLID',color:{r:parseInt(h.slice(1,3),16)/255,g:parseInt(h.slice(3,5),16)/255,b:parseInt(h.slice(5,7),16)/255}});
function recolor(node){
  if(node.type==='VECTOR'){node.fills=[S(GRAY)];return 1;}
  let n=0;
  for(const v of node.findAll(x=>x.type==='VECTOR')){v.fills=[S(GRAY)];n++;}
  return n;
}
for(const [sid,x] of srcs){
  const comp=await C(sid);
  const clone=comp.children[0].clone();
  gray.appendChild(clone);
  clone.x=x; clone.y=0;
  out['icon@'+x]={ty:clone.type,x:Math.round(clone.x),y:Math.round(clone.y),w:Math.round(clone.width),h:Math.round(clone.height),vecs:recolor(clone)};
}
out.grayKids=gray.children.map(k=>k.name+' x'+Math.round(k.x)+' y'+Math.round(k.y)+' w'+Math.round(k.width)+' h'+Math.round(k.height));
